  values ('ME', 'short_answer', 'Calculate the seed rate per hectare of a 7 × 17 cm seed drill (7 furrow openers spaced 17 cm apart), whose main drive wheel is 124 cm in diameter and the total weight of grain collected in 20 revolutions is 0.423 kg. (5 marks)', 'Width covered = 7 × 0.17 = 1.19 m. Distance travelled = π × 1.24 × 20 = 77.9 m. Area = 1.19 × 77.9 = 92.7 m². Seed rate = 0.423 kg / 92.7 m² × 10,000 = 45.6 kg per hectare.', null, '[{"point": "Width = 7 × 0.17 = 1.19 m", "marks": 1}, {"point": "Distance = π × 1.24 × 20 = 77.9 m", "marks": 1}, {"point": "Area = 1.19 × 77.9 = 92.7 m²", "marks": 1}, {"point": "Seed rate = 0.423 × 10,000 / 92.7", "marks": 1}, {"point": "≈ 45.6 kg/ha", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
